            if neighbor not in distances or current_length + weight < distances[neighbor]:
                distances[neighbor] = current_length + weight
                paths[neighbor] = paths[current_node] + [neighbor]
                heappush(queue, (neighbor, distances[neighbor]))

    # If we can't reach the target, return infinity and None
