from collections import deque
from itertools import count
from math import inf

def shortest_path(graph, source, target):
    with_negative = [inf] * len(graph)
    with_positive = [inf] * len(graph)
    index_map = {node: idx for idx, node in enumerate(graph)}
    queue = [(0, source, [source])]
    while queue:
        cur_dist, node, path = queue.pop(0)
        if cur_dist > with_negative[index_map[node]]:
            continue
        if cur_dist < with_negative[index_map[node]]:
            with_negative[index_map[node]] = cur_dist
            for neighbor, weight in graph[node]:
                queue.append((cur_dist + weight, neighbor, path + [neighbor]))
        else:
            for neighbor, weight in graph[node]:
                new_dist = cur_dist + weight
                if new_dist < with_positive[index_map[neighbor]]:
                    with_positive[index_map[neighbor]] = new_dist
                    queue.append((new_dist, neighbor, path + [neighbor]))
        if node == target:
            return (with_positive[index_map[target]], path)
    return (inf, None)
