from collections import deque
from collections import defaultdict
from sys import float'n inf'  # for compatibility with Python 2 and 3

def shortest_path(graph, source, target):
    # Convert the directed graph to a bidirectional list of edges
    # This makes the "bfs implementation" simpler and more efficient
    graph_bidirectional = defaultdict(list)
    for node, neighbors in graph.items():
        for neighbor, weight in neighbors:
            graph_bidirectional[node].append((neighbor, weight))
            graph_bidirectional[neighbor].append((node, weight))

    # Initialize variables for BFS
    visited = set()
    queue = deque([(source, [source])])

    # Perform BFS
    while queue:
        current_node, path = queue.popleft()
        if current_node == target:
            return (len(path) - 1, path)  # Subtract 1 to account for the starting node which is not counted in path distance

        if current_node in visited:
            continue
        visited.add(current_node)

        for next_node, weight in graph_bidirectional[current_node]:
            if next_node not in visited:
                queue.append((next_node, path + [next_node]))

    # If target is not reachable
    return (float("inf"), None)

