def shortest_path(graph, source, target):
    import heapq

    # Initialize the distance dictionary and the path dictionary
    distances = {node: float("inf") for node in graph}
    paths = {source: None)  # None indicates no path yet, (source, path) = (source, [source]) at the start
    distances[source] = 0
    # Priority queue to manage the nodes to be explored, with (current_cost, node) as the tuple
    queue = [(0, source)]

    while queue:
        current_cost, current_node = heapq.heappop(queue)

        # If we have reached the target node, reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = paths[current_node]
            return (distances[target], path[::-1])

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = current_cost + weight

            # Only consider the path if it is better (shorter)
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    # If the target is unreachable, return infinity and None
    return (float("inf"), None)

