from math import inf

def shortest_path(graph, source, target):
    distances = dict()
    paths = dict()
    shortest_paths = dict()
    for node in graph:
        distances[node] = inf
        paths[node] = None
        shortest_paths[node] = []
    distances[source] = 0
    queue = deque([source])
    while queue:
        current = queue.popleft()
        for neighbor, weight in graph.get(current, []):
            new_distance = distances[current] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                paths[neighbor] = current
                shortest_paths[neighbor] = shortest_paths[current] + [neighbor]
                if neighbor not in queue:
                    queue.append(neighbor)
    if distances[target] == inf:
        return (inf, None)
    current = target
    shortest_path = [current]
    while current != source:
        current = paths[current]
        shortest_path.append(current)
    shortest_path.reverse()
    return (distances[target], shortest_path)

from collections import deque
from math import inf

def shortest_path(graph, source, target):
    status = set()
    distance = [(inf, None) for _ in graph]
    distances = [inf for _ in graph]
    distances[source] = 0
    path = [source] + [None] * (max(graph.keys()) + 1)
    queue = deque([(source, 0)])
    while queue:
        current_node, current_distance = queue.popleft()
        if current_node in status:
            continue
        status.add(current_node)
        for neighbor, weight in graph.get(current_node, []):
            new_distance = current_distance + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                path[neighbor] = current_node
                queue.append((neighbor, new_distance))
    if distances[target] == inf:
        return (inf, None)
    else:
        reconstructed_path = []
        current_node = target
        while current_node is not None:
            reconstructed_path.append(current_node)
            current_node = path[current_node]
        reconstructed_path.reverse()
        return (distances[target], reconstructed_path)
